888	static bool device_id_in_list(u16 device_id, const char *devices, bool negative)
889	{
890		char *s, *p, *tok;
891		bool ret;
892	
893		if (!devices || !*devices)
894			return false;
895	
896		/* match everything */
897		if (negative && strcmp(devices, "!*") == 0)
898			return true;
899		if (!negative && strcmp(devices, "*") == 0)
900			return true;
901	
902		s = kstrdup(devices, GFP_KERNEL);
903		if (!s)
904			return false;
905	
906		for (p = s, ret = false; (tok = strsep(&p, ",")) != NULL; ) {
907			u16 val;
908	
909			if (negative && tok[0] == '!')
910				tok++;
911			else if ((negative && tok[0] != '!') ||
912				 (!negative && tok[0] == '!'))
913				continue;
914	
915			if (kstrtou16(tok, 16, &val) == 0 && val == device_id) {
916				ret = true;
917				break;
918			}
919		}
920	
921		kfree(s);
